"""Reproduce three exact finite suites; all fixtures and original scripts retained.
Requires Python 3 and sympy. Results are written under ./exact_check_output.
The finite examples do not evaluate native xi data."""
from pathlib import Path
import json
ROOT=Path(__file__).parent/'exact_check_output'
ROOT.mkdir(exist_ok=True)
SCRIPTS=json.loads('{"check_adjacent_current.py": "from pathlib import Path\\nimport sympy as s,json,hashlib\\nP=Path(__file__).parent\\nI=s.I;t=s.symbols(\'t\',real=True); checks=[]\\ndef eq(a,b,name):\\n    if isinstance(a,s.MatrixBase): good=all(s.simplify(z)==0 for z in a-b)\\n    else: good=s.simplify(a-b)==0\\n    if not good: raise AssertionError(name)\\n    checks.append(name)\\ndef ip(x,y,G):return (x.conjugate().T*G*y)[0]\\ndef canon(X):return X.applyfunc(s.expand_complex).applyfunc(s.simplify)\\ndef derive(G,K,U,A,x,label):\\n    print(\'checking \'+label,flush=True)\\n    n=G.rows;d=U.cols\\n    H=canon(K.H*G*K);Pr=canon(K*H.inv()*K.H*G)\\n    E=canon(Pr*U);F=canon((s.eye(n)-Pr)*U);alpha=canon(U.H*G*U);beta=canon(F.H*G*F)\\n    D=s.eye(d)+t*alpha;B=s.eye(d)+t*beta\\n    dt=s.factor(D.det());bt=s.factor(B.det())\\n    Delta=D.adjugate();Badj=B.adjugate()\\n    p=canon(Pr*x);o=canon(x-p);rho=canon(F.H*G*x)\\n    vp=bt*p-t*E*Badj*rho;vo=bt*o+t*E*Badj*rho\\n    GN=dt*G-t*G*U*Delta*U.H*G\\n    Z=s.Poly(s.expand((vp.H*GN*A*vo)[0]),t)\\n    W=s.Poly(s.expand(((bt*o.H*G-t*rho.H*Badj*F.H*G)*A*vp)[0]),t)\\n    R=s.Poly(s.expand(s.re(s.conjugate(Z.as_expr())*W.as_expr())),t)\\n    assert Z.degree()<=3*d and W.degree()<=2*d and R.degree()<=5*d\\n    checks.append(label+\':degree\')\\n    for tv in [s.Rational(0),s.Rational(1,3),s.Rational(1),s.Rational(3,2)]:\\n        gt=canon(canon(G.inv()+tv*U*U.H).inv())\\n        ht=canon(K.H*gt*K)\\n        pt=canon(K*ht.inv()*K.H*gt)\\n        px=pt*x;ox=x-px\\n        zd=ip(px,A*ox,gt);wd=ip(ox,A*px,gt)\\n        at=s.eye(d)+tv*alpha;be=s.eye(d)+tv*beta\\n        tag=f\'{label}:t={tv}\'\\n        eq(gt,G-tv*G*U*at.inv()*U.H*G,tag+\':inverse\')\\n        eq(pt,Pr-tv*E*be.inv()*F.H*G,tag+\':projection\')\\n        eq(ht.det()/H.det(),be.det()/at.det(),tag+\':kernel-det\')\\n        eq(zd,Z.eval(tv)/(dt.subs(t,tv)*bt.subs(t,tv)**2),tag+\':z\')\\n        eq(wd,W.eval(tv)/bt.subs(t,tv)**2,tag+\':w\')\\n        eq(s.re(s.conjugate(zd)*wd),R.eval(tv)/(dt.subs(t,tv)*bt.subs(t,tv)**4),tag+\':phase\')\\n    if d==1:\\n        u=U[:,0];e=E[:,0];f=F[:,0];rr=rho[0];aa=alpha[0];bb=beta[0]\\n        p1=bb*p-rr*e;o1=bb*o+rr*e\\n        J0=ip(p,A*o,G);J1=ip(p1,A*o,G)+ip(p,A*o1,G);J2=ip(p1,A*o1,G)\\n        T0=ip(p,u,G)*ip(u,A*o,G)\\n        T1=ip(p1,u,G)*ip(u,A*o,G)+ip(p,u,G)*ip(u,A*o1,G)\\n        T2=ip(p1,u,G)*ip(u,A*o1,G)\\n        zc=[J0,J1+aa*J0-T0,J2+aa*J1-T1,aa*J2-T2]\\n        L=rr*ip(o,A*e,G)+s.conjugate(rr)*ip(f,A*p,G)\\n        w0=ip(o,A*p,G);wc=[w0,2*bb*w0-L,bb**2*w0-bb*L+rr*s.conjugate(rr)*ip(f,A*e,G)]\\n        eq(Z.as_expr(),sum(zc[j]*t**j for j in range(4)),label+\':all-z-coefficients\')\\n        eq(W.as_expr(),sum(wc[j]*t**j for j in range(3)),label+\':all-w-coefficients\')\\n    return Z.degree(),W.degree(),R.degree()\\nG=s.diag(2,3,5)\\nK=s.Matrix([[1,0],[0,1],[0,0]])\\nA=s.Matrix([[2+I,1,2*I],[0,-1+2*I,1],[I,1,3-I]])\\nx=s.Matrix([1+I,2-I,3])\\nU=s.Matrix([1,I,2])\\ndegrees={}\\ndegrees[\'complex_rank_one\']=derive(G,K,U,A,x,\'complex_rank_one\')\\ndegrees[\'complex_rank_two\']=derive(G,K,U.row_join(s.Matrix([I,2,1-I])),A,x,\'complex_rank_two\')\\ndegrees[\'dependent_columns\']=derive(G,K,U.row_join(2*U),A,x,\'dependent_columns\')\\nPr=K*(K.H*G*K).inv()*K.H*G\\ndegrees[\'column_in_kernel\']=derive(G,K,K[:,0],A,x,\'column_in_kernel\')\\ndegrees[\'zero_column\']=derive(G,K,s.zeros(3,1),A,x,\'zero_column\')\\n# A genuine adjacent polynomial-source fixture: full complex quartet and full ideals.\\ny=s.symbols(\'y\'); roots=[3-I/4,3+I/4,-3-I/4,-3+I/4]\\npolys=[s.Integer(1),y]; norms=[s.Integer(1),s.Rational(1,2)]\\nfor j in range(1,9):\\n    polys.append(s.expand(y*polys[-1]-j*(j-s.Rational(1,2))*polys[-2]))\\n    norms.append(s.factor(norms[-1]*(j+1)*(j+s.Rational(1,2))))\\nC=s.zeros(4)\\nCs={}\\nfor j in range(9):\\n    col=s.Matrix([polys[j].subs(y,r) for r in roots])\\n    C+=col*col.H/norms[j]\\n    if j in [3,4,7,8]:Cs[j]=s.simplify(C)\\nB=s.Matrix([[1,0],[0,1],[I,1],[1,-I]])\\nfor N in [3,7]:\\n    print(\'checking polynomial source \'+str(N),flush=True)\\n    col=s.Matrix([polys[N+1].subs(y,r) for r in roots])\\n    col=canon(col);G0=canon(Cs[N]).inv();G1=canon(Cs[N+1]).inv()\\n    G0=canon(G0);G1=canon(G1)\\n    P0=canon(B*canon(B.H*G0*B).inv()*B.H*G0)\\n    aa=ip(col,col,G0)/norms[N+1]\\n    ff=(s.eye(4)-P0)*col\\n    bb=ip(ff,ff,G0)/norms[N+1]\\n    eq(canon(B.H*G1*B).det()/canon(B.H*G0*B).det(),(1+bb)/(1+aa),f\'quartet N={N}:full-ideal endpoint allocation\')\\n# Exact joint source inclusion and its correlated activated columns.\\nLmap=s.Matrix([[1,0,I,1,2],[0,1,1,I,1]])\\nX=s.eye(5)[:,:2];v=s.eye(5)[:,2]\\nY=s.Matrix([1,I,1,1,0]);XY=X.row_join(Y)\\nPXY=XY*(XY.H*XY).inv()*XY.H\\njn=(s.eye(5)-PXY)*v;gn=Lmap*jn/s.sqrt((jn.H*jn)[0]);fn=Lmap*v\\nXYnext=X.row_join(v).row_join(Y)\\nPnew=XYnext*(XYnext.H*XYnext).inv()*XYnext.H\\nC0=Lmap*X*X.H*Lmap.H;CJ0=Lmap*PXY*Lmap.H\\nC1=C0+fn*fn.H;CJ1=Lmap*Pnew*Lmap.H\\neq(CJ1-CJ0,gn*gn.H,\'joint-source exact new-column\')\\neta=s.Rational(1,3);Ca=(1-eta)*C0+eta*CJ0;Can=(1-eta)*C1+eta*CJ1\\nUa=s.sqrt(1-eta)*fn;Va=s.sqrt(eta)*gn;Ga=Ca.inv()\\neq(Can-Ca,Ua*Ua.H+Va*Va.H,\'actual activated rank-two increment\')\\ncross=ip(Ua,Va,Ga)\\neq(Can.det()/Ca.det(),(1+ip(Ua,Ua,Ga))*(1+ip(Va,Va,Ga))-cross*s.conjugate(cross),\'rank-two cross determinant\')\\nassert s.simplify(cross)!=0;checks.append(\'negative-control:omitting-cross-term-changes-determinant\')\\n# A13 Taylor matching with exact Gaussian moments, on both parities.\\ndef moment(j):\\n    return s.Integer(0) if j%2 else s.factorial2(j-1) if j else s.Integer(1)\\nfor n in range(3,8):\\n    Gram=s.Matrix(n+1,n+1,lambda i,j:moment(i+j))\\n    coeff=-Gram[:n,:n].inv()*Gram[:n,n]\\n    mon=s.Matrix(list(coeff)+[1]);omega=(mon.T*Gram*mon)[0]\\n    for ell in range(1,n):\\n        r=n-ell; WG=s.Matrix(r+1,r+1,lambda i,j:moment(2*ell+i+j))\\n        ucoeff=-WG[:r,:r].inv()*WG[:r,r]\\n        Umon=s.Matrix(list(ucoeff)+[1]);nu=(Umon.T*WG*Umon)[0]\\n        G0=Gram[:n,:n];fix=coeff[:ell,0]\\n        lowG=G0[:ell,:ell];cr=G0[:ell,ell:n];high=G0[ell:n,ell:n]\\n        attained=(fix.T*(lowG-cr*high.inv()*cr.T)*fix)[0]/omega\\n        eq(attained,nu/omega-1,f\'Taylor minimum n={n} L={ell}\')\\nout={\'status\':\'passed\',\'exact_checks\':len(checks),\'checks\':checks,\'degrees\':{k:list(map(str,v)) for k,v in degrees.items()},\'scope\':\'Exact algebraic and original-polynomial-source fixtures. Auxiliary parameter and kernel fixtures do not evaluate the actual programme period or an asymptotic coefficient.\'}\\n(P/\'ADJACENT_CURRENT_EXACT_CHECKS.json\').write_text(json.dumps(out,indent=2)+\'\\\\n\')\\nprint(json.dumps({k:out[k] for k in [\'status\',\'exact_checks\',\'degrees\']}))\\n", "check_activated_current_independent.py": "\\"\\"\\"Exact independent tests for ACD1--15, not numerical asymptotics.\\"\\"\\"\\nfrom pathlib import Path\\nimport json\\nimport sympy as s\\n\\nt=s.symbols(\'t\', real=True)\\nI=s.I\\nchecks=[]\\ndef ck(name, value):\\n    if isinstance(value, s.MatrixBase):\\n        ok=all(s.cancel(s.expand_complex(z))==0 for z in value)\\n    else:\\n        ok=bool(value)\\n    checks.append({\'name\':name,\'passed\':ok})\\n    if not ok: raise AssertionError(name)\\n\\nG=s.eye(3)\\nK=s.Matrix([1,1,0])\\nU0=s.Matrix([[1,0],[0,1],[1,1+I]])\\nA=s.diag(1+I,2+3*I,4+5*I)\\nx=s.Matrix([1,0,0])\\nH=K.H*G*K\\nP=K*H.inv()*K.H*G\\nframes=[(\'noncommuting\',U0),(\'dependent\',s.Matrix.hstack(U0[:,0],(1+I)*U0[:,0])),\\n        (\'zero_second\',s.Matrix.hstack(U0[:,0],s.zeros(3,1))),(\'zero\',s.zeros(3,2))]\\nfixture={}\\nfor name,U in frames:\\n    E=P*U; F=(s.eye(3)-P)*U\\n    AA=U.H*G*U; BB=F.H*G*F\\n    D=s.eye(2)+t*AA; B=s.eye(2)+t*BB\\n    d=s.expand(D.det()); b=s.expand(B.det())\\n    p=P*x; o=x-p; rho=F.H*G*x\\n    Delta=D.adjugate(); BA=B.adjugate()\\n    v=s.expand(b)*p-t*E*BA*rho\\n    wv=s.expand(b)*o+t*E*BA*rho\\n    Z=s.expand((v.H*(d*G-t*G*U*Delta*U.H*G)*A*wv)[0])\\n    W=s.expand(((b*o.H*G-t*rho.H*BA*F.H*G)*A*v)[0])\\n    R=s.simplify(s.expand_complex(s.conjugate(Z)*W).as_real_imag()[0])\\n    degree=lambda z: -1 if z==0 else int(s.Poly(z,t).degree())\\n    degs=[degree(Z),degree(W),degree(R)]\\n    ck(name+\':degrees\',all(a<=bnd for a,bnd in zip(degs,[6,4,10])))\\n    if name==\'noncommuting\':\\n        ck(\'noncommuting:commutator_present\',AA*BB-BB*AA!=s.zeros(2))\\n        fixture.update({\'A\':str(AA),\'B\':str(BB),\'commutator\':str(AA*BB-BB*AA),\\n                        \'d\':str(d),\'b\':str(b),\'degrees\':degs})\\n    for tv in [s.Integer(0),s.Rational(2,3),s.Integer(1),s.Integer(3)]:\\n        Gt=(G.inv()+tv*U*U.H).inv()\\n        Ht=K.H*Gt*K\\n        Pt=K*Ht.inv()*K.H*Gt\\n        Bt=B.subs(t,tv); Dt=D.subs(t,tv)\\n        lbl=name+\':\'+str(tv)\\n        ck(lbl+\':metric\',Gt-(G-tv*G*U*Dt.inv()*U.H*G))\\n        ck(lbl+\':projection\',Pt-(P-tv*E*Bt.inv()*F.H*G))\\n        L=K.H*G*U\\n        ck(lbl+\':kernel_inverse\',Ht.inv()-(H.inv()+tv*H.inv()*L*Bt.inv()*L.H*H.inv()))\\n        ck(lbl+\':determinant\',s.simplify(Ht.det()/H.det()-b.subs(t,tv)/d.subs(t,tv))==0)\\n        ot=(s.eye(3)-Pt)*x; pt=Pt*x\\n        ck(lbl+\':ordered_product\',U.H*G*ot-Dt*Bt.inv()*rho)\\n        ck(lbl+\':row_cancellation\',ot.H*Gt-(o.H*G-tv*rho.H*Bt.inv()*F.H*G))\\n        z=(pt.H*Gt*A*ot)[0]; w=(ot.H*Gt*A*pt)[0]\\n        ck(lbl+\':z\',s.simplify(z-Z.subs(t,tv)/(d.subs(t,tv)*b.subs(t,tv)**2))==0)\\n        ck(lbl+\':w\',s.simplify(w-W.subs(t,tv)/b.subs(t,tv)**2)==0)\\n        direct=s.simplify(s.expand_complex(s.conjugate(z)*w).as_real_imag()[0])\\n        ck(lbl+\':current\',s.simplify(direct-R.subs(t,tv)/(d.subs(t,tv)*b.subs(t,tv)**4))==0)\\n        if name==\'noncommuting\' and tv==1:\\n            wrong=s.simplify(U.H*G*ot-Bt.inv()*Dt*rho)\\n            ck(\'negative_control:reversed_order_fails\',wrong!=s.zeros(2,1))\\n            fixture[\'wrong_order_residual\']=str(wrong)\\n            fixture[\'current_at_one\']=str(direct)\\n            wrong_den=s.simplify(R.subs(t,1)/(d.subs(t,1)**2*b.subs(t,1)**4))\\n            ck(\'negative_control:extra_d_fails\',wrong_den!=direct)\\n\\n# A finite Hilbert-source inclusion with a source vector of zero value.\\n# This checks that covariance addition uses the orthogonal residual, rather\\n# than discarding a relation before constructing that residual.\\nV=s.Matrix([[1,2,0],[0,1,0]])\\nphi=s.Matrix([0,0,1])\\nX=s.Matrix([1,0,0]); Y=s.Matrix([0,1,1])\\njoint=s.Matrix.hstack(X,Y)\\nPj=joint*(joint.H*joint).inv()*joint.H\\nz=(s.eye(3)-Pj)*phi\\nCj=V*Pj*V.H\\nCnext=V*V.H\\nck(\'source_inclusion:joint_residual\',Cnext-Cj-(V*z)*(V*z).H/(z.H*z)[0])\\nck(\'source_inclusion:scalar_zero_value\',V*phi)\\nck(\'source_inclusion:joint_value_survives\',V*z!=s.zeros(2,1))\\n\\n# Rank-one relative determinant on a nested family of fixed functionals.\\nR0=s.Matrix([[2,1],[1,3]])\\nC0=2*R0\\na=s.Matrix([1,1+I])\\nC1=C0+a*a.H\\ninc=s.cancel(C1.det()/C0.det())\\nck(\'fixed_functionals:determinant\',s.simplify(inc-(1+(a.H*C0.inv()*a)[0]))==0)\\nrel=C0.inv()*C1\\nck(\'fixed_functionals:one_unit_eigenvalue\',s.simplify((rel-s.eye(2)).det())==0)\\nck(\'fixed_functionals:other_eigenvalue\',s.simplify(rel.trace()-1-inc)==0)\\n\\n# A diagonal-action/eigenclass example attains degree ten. This witnesses\\n# the general algebraic bound only; it is not a programme cutoff value.\\nG4=s.eye(4); K4=s.Matrix([1,1,0,0])\\nU4=s.Matrix([[1,0],[0,1],[1,1+I],[2,1-I]])\\nA4=s.diag(1+I,2+3*I,4+5*I,6+7*I); x4=s.Matrix([1,0,0,0])\\nP4=K4*(K4.H*K4).inv()*K4.H\\nE4=P4*U4; F4=(s.eye(4)-P4)*U4\\nD4=s.eye(2)+t*U4.H*U4; B4=s.eye(2)+t*F4.H*F4\\nd4=s.expand(D4.det()); b4=s.expand(B4.det()); rho4=F4.H*x4\\nv4=b4*P4*x4-t*E4*B4.adjugate()*rho4\\nw4=b4*(s.eye(4)-P4)*x4+t*E4*B4.adjugate()*rho4\\nZ4=s.expand((v4.H*(d4*G4-t*U4*D4.adjugate()*U4.H)*A4*w4)[0])\\nW4=s.expand(((b4*x4.H*(s.eye(4)-P4)-t*rho4.H*B4.adjugate()*F4.H)*A4*v4)[0])\\nR4=s.expand(s.expand_complex(s.conjugate(Z4)*W4).as_real_imag()[0])\\nck(\'degree_ten:attained\',s.degree(R4,t)==10)\\nck(\'degree_ten:leading_coefficient\',s.Poly(R4,t).LC()==s.Rational(2478125,8))\\nfixture[\'degree_ten_example\']={\'d\':str(d4),\'b\':str(b4),\'degree\':10,\'leading_coefficient\':\'2478125/8\'}\\n\\nout={\'scope\':\'ACD exact independent fixtures; no native asymptotic evaluation\',\\n     \'passed\':len(checks),\'checks\':checks,\'noncommuting_fixture\':fixture}\\nPath(__file__).with_name(\'ACTIVATED_CURRENT_INDEPENDENT_CHECKS.json\').write_text(\\n    json.dumps(out,indent=2),encoding=\'utf-8\')\\nprint(json.dumps({\'passed\':len(checks),\'noncommuting_fixture\':fixture},indent=2))\\n", "check_original_projection_cauchy.py": "\\"\\"\\"Exact finite checks of CGP5--6, CGP18 and CGP23--24.\\"\\"\\"\\nimport json\\nfrom pathlib import Path\\nimport sympy as s\\n\\nBASE=Path(__file__).resolve().parent\\nx=s.symbols(\'x\');checks=[]\\n\\ndef ok(name,truth):\\n    if truth is not True and truth!=s.true:\\n        raise AssertionError(name)\\n    checks.append(name)\\n\\ndef zero(a):\\n    return all(s.simplify(v)==0 for v in a)\\n\\ndef pd(a):\\n    a=a.applyfunc(s.simplify)\\n    return zero(a-a.conjugate().T) and all(\\n        s.simplify(a[:j,:j].det())>0 for j in range(1,a.rows+1))\\n\\nP=[s.Integer(1),x]\\nfor n in range(1,8):\\n    P.append(s.expand(x*P[-1]-n*s.Rational(2*n-1,2)*P[-2]))\\ngam=lambda n:s.factorial(n)*s.rf(s.Rational(1,2),n)\\npoints=[s.Integer(0),s.Rational(2,3),s.Rational(-1,2)+s.I/3]\\nfor D in range(7):\\n    for a in points:\\n        for z in points:\\n            b=s.conjugate(z)\\n            direct=sum(P[n].subs(x,a)*P[n].subs(x,b)/gam(n) for n in range(D+1))\\n            if a!=b:\\n                cd=(P[D+1].subs(x,a)*P[D].subs(x,b)-\\n                    P[D].subs(x,a)*P[D+1].subs(x,b))/(gam(D)*(a-b))\\n            else:\\n                cd=(s.diff(P[D+1],x)*P[D]-s.diff(P[D],x)*P[D+1]).subs(x,a)/gam(D)\\n            ok(f\'CGP6 full Christoffel-Darboux D={D} x={a} z={z}\',\\n               s.simplify(cd-direct)==0)\\n\\nD=5\\nroots=[s.Integer(a)+s.I*s.Rational(b,4) for a in [-3,3] for b in [-1,1]]\\nE=s.Matrix(4,D+1,lambda i,n:P[n].subs(x,roots[i])/s.sqrt(gam(n)))\\nG=s.simplify(E*E.conjugate().T)\\nPI=s.simplify(s.eye(D+1)-E.conjugate().T*G.inv()*E)\\nok(\'CGP5 complete lower-root projection idempotent\',zero(PI*PI-PI))\\nok(\'CGP5 complete lower-root projection self-adjoint\',zero(PI-PI.conjugate().T))\\nok(\'CGP5 every lower-root row killed\',zero(E*PI))\\nok(\'CGP5 exact original source dimension\',PI.rank()==D+1-len(roots))\\nchi=s.prod(x-a for a in roots)\\nPhi=s.Matrix(D+1,D+1,lambda i,j:s.Poly(P[j],x).nth(i)/s.sqrt(gam(j)))\\nEmb=s.Matrix(D+1,2,lambda i,j:s.Poly(chi*x**j,x).nth(i))\\nB=Phi.inv()*Emb\\nPI2=s.simplify(B*(B.conjugate().T*B).inv()*B.conjugate().T)\\nok(\'CGP5 matches full chi-prime source projection\',zero(PI-PI2))\\n\\n# Discrete Cauchy alias tests with exact roots of unity. These rational\\n# analytic fixtures test the analytic identity, not the original period.\\nrc=s.Rational(1,2)\\nfor alpha in [s.Rational(1,3),-s.Rational(1,4),s.I/3]:\\n    for T in [4,8]:\\n        for n in range(min(T,6)):\\n            omega=[s.expand_complex(s.exp(2*s.pi*s.I*j/T)) for j in range(T)]\\n            sample=s.simplify(sum(1/(1-alpha*rc*w)*w**(-n) for w in omega)/(T*rc**n))\\n            alias=alpha**n/(1-(alpha*rc)**T)\\n            ok(f\'CGP18 exact DFT alias alpha={alpha} T={T} n={n}\',\\n               s.simplify(sample-alias)==0)\\n\\nalpha=[s.Rational(1,3),-s.Rational(1,4)]\\nrho=lambda n:s.sqrt(s.factorial(n)/s.rf(s.Rational(1,2),n))\\nW=s.Matrix(2,D+1,lambda i,n:rho(n)*alpha[i]**n)\\nCt=s.simplify(W*W.conjugate().T)\\nC=s.simplify(W*PI*W.conjugate().T)\\nok(\'CGP16 exact projected covariance positive\',pd(C))\\nok(\'CGP16 exact unprojected covariance positive\',pd(Ct))\\nok(\'negative control original projection changes covariance\',not zero(C-Ct))\\n# det(C)/trace(C) is a proved lower eigenvalue bound for a positive 2x2 C.\\nlam=min(s.Integer(1),s.cancel(C.det()/s.trace(C)))\\nouter=s.Rational(3,4)\\n# On |t|<=3/4 the two rational functions have joint row bound <=2.\\nBN2=s.Integer((D+1)*(2*D+1)*4)*outer**(-2*D)\\nT=D+1\\nwhile (rc/outer)**T>lam/(32*BN2):\\n    T+=1\\nok(\'CGP20 selected integer satisfies exact finite guard\',\\n   T>D and (rc/outer)**T<=lam/(32*BN2))\\nWT=s.Matrix(2,D+1,lambda i,n:rho(n)*alpha[i]**n/(1-(alpha[i]*rc)**T))\\nCT=s.simplify(WT*PI*WT.conjugate().T)\\nCtT=s.simplify(WT*WT.conjugate().T)\\nok(\'CGP23 projected lower relative bound\',pd(CT-s.Rational(3,4)*C))\\nok(\'CGP23 projected upper relative bound\',pd(s.Rational(5,4)*C-CT))\\nok(\'CGP23 full-source lower relative bound\',pd(CtT-s.Rational(3,4)*Ct))\\nok(\'CGP23 full-source upper relative bound\',pd(s.Rational(5,4)*Ct-CtT))\\nratio=s.cancel((CT.det()/CtT.det())/(C.det()/Ct.det()))\\nok(\'CGP24 logarithmic determinant allowance in multiplicative form\',\\n   s.Rational(3,4)**4<=ratio<=s.Rational(4,3)**4)\\nok(\'CGP24 sample source has no artificial projection isometry\',\\n   0<s.cancel(CT.det()/CtT.det())<1)\\n\\nreport={\'status\':\'passed\',\'checks\':len(checks),\'details\':checks,\\n \'auxiliary_sample_count\':T,\\n \'scope\':\'Exact Gamma Christoffel-Darboux, complete lower-root projection, discrete Cauchy aliases and finite relative covariance/determinant bounds.\',\\n \'mass\':\'A common sqrt(2*pi) Gamma mass is factored out on both sides in the auxiliary exact fixtures; the mathematical proof retains that mass.\',\\n \'not_claimed\':\'No numerical leading coefficient or sign of the original period-dependent four-angle determinant.\'}\\n(BASE/\'ORIGINAL_PROJECTION_CAUCHY_CHECKS.json\').write_text(json.dumps(report,indent=2)+\'\\\\n\',encoding=\'utf-8\')\\nprint(json.dumps({\'status\':\'passed\',\'checks\':len(checks),\'auxiliary_sample_count\':T}))\\n"}')
for name,source in SCRIPTS.items():
    location=ROOT/name
    location.write_text(source,encoding='utf-8')
    exec(compile(source,str(location),'exec'),{'__name__':'__main__','__file__':str(location)})
